// Exact inference functions from .1118 commit 8218a63b1a5594fd338e23601e8220b6dc0fb596; test-only baseline.
function screenPoint(point,camera){const p=point.clone().project(camera),r=canvas.getBoundingClientRect();return{x:r.left+(p.x*.5+.5)*r.width,y:r.top+(-p.y*.5+.5)*r.height};}
function referenceUnderPointer(event,d){if(event.pointerId===9876||!inferenceToggle?.checked)return null;const m=d.before,camera=d.camera,selectedFaces=new Set(d.faces),selectedVertices=new Set();d.faces.forEach(fi=>(m.faces[fi]||[]).forEach(v=>selectedVertices.add(v)));let bestV=null;m.vertices.forEach((v,i)=>{if(selectedVertices.has(i))return;const sp=screenPoint(v,camera),dist=Math.hypot(event.clientX-sp.x,event.clientY-sp.y);if(dist<=REF_VERTEX_PX&&(!bestV||dist<bestV.d))bestV={type:'Vertex',index:i,point:v.clone(),d:dist};});if(bestV)return bestV;let bestE=null;m.edges().forEach((e,i)=>{if(selectedVertices.has(e.a)&&selectedVertices.has(e.b))return;const a=screenPoint(m.vertices[e.a],camera),b=screenPoint(m.vertices[e.b],camera),vx=b.x-a.x,vy=b.y-a.y,l2=vx*vx+vy*vy;if(l2<1)return;const t=THREE.MathUtils.clamp(((event.clientX-a.x)*vx+(event.clientY-a.y)*vy)/l2,0,1),qx=a.x+vx*t,qy=a.y+vy*t,dist=Math.hypot(event.clientX-qx,event.clientY-qy);if(dist<=REF_EDGE_PX&&(!bestE||dist<bestE.d))bestE={type:'Edge',index:i,point:m.vertices[e.a].clone().lerp(m.vertices[e.b],t),d:dist};});if(bestE)return bestE;setPointer(event);raycaster.setFromCamera(pointer,camera);let bestF=null;m.faces.forEach((f,fi)=>{if(selectedFaces.has(fi))return;const positions=[];for(let i=1;i<f.length-1;i++)for(const vi of[f[0],f[i],f[i+1]]){const v=m.vertices[vi];positions.push(v.x,v.y,v.z);}if(!positions.length)return;const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));const mat=new THREE.MeshBasicMaterial({side:THREE.DoubleSide}),obj=new THREE.Mesh(g,mat),hit=raycaster.intersectObject(obj,false)[0];g.dispose();mat.dispose();if(hit&&(!bestF||hit.distance<bestF.distance))bestF={type:'Face',index:fi,point:hit.point.clone(),distance:hit.distance};});return bestF;}
